#!/usr/bin/env python3
import csv, sys

INV = "/home/nick/work/andesim/tests/andes_csr/csr_inventory.csv"
MINE = "/tmp/claude-1002/-home-nick-work-andesim/9fb5c597-ba1e-4046-8ada-d69e84b4f335/scratchpad/mine.csv"
OUT = "/tmp/claude-1002/-home-nick-work-andesim/9fb5c597-ba1e-4046-8ada-d69e84b4f335/scratchpad/opus_review.csv"

def norm(s):
    return s.replace('ﬂ','fl').replace('ﬁ','fi')

# ---- ground-truth sets (engine ax45mpv_premium) ----
ALWAYS_STD = {'mstatus','mie','mtvec','mepc','mcause','mtval','mscratch','mip',
              'mcycle','minstret','mcache_ctl','mmisc_ctl'}
FP = {'fcsr','frm','fflags'}
IMPL = {'mxstatus','mclk_ctl','milmb','mdlmb','mcountermask_m','uitb','jvt',
        'pmacfg0','pmacfg2','mcountinhibit','mcounterinten','mdcause',
        'tselect','tdata2','tcontrol','mcontext'}
DONE_RANGE = {'mhpmcounter3~6','mhpmevent3~6','pmaaddr0~47'}

# na: S-mode/Hyp specific M-priv regs
NA_S = {'medeleg','mideleg','mcountermask_s','mslideleg','scontext','satp'}
# na: read-only WARL-fixed
WARL_FIXED = {'misa','tdata3','tinfo'}
HIGH_HALF = {'menvcfgh','mseccfgh','mcycleh','minstreth',
             'mstateen0h','mstateen1h','mstateen2h','mstateen3h',
             'cycleh','timeh','instreth','mcache_ctl2'}
ODD_PMACFG = {'pmacfg1','pmacfg3','pmacfg5','pmacfg7','pmacfg9','pmacfg11'}
SIDE_EFF = {'mnxti','mscratchcsw','mscratchcswl','mcctlcommand','mintsel_jal',
            'pushmcause','pushmepc','pushmxstatus','wfe','txevt','ucctlcommand'}
INDIRECT = {'miselect','mireg','mireg2','mireg3','mireg4','mireg5','mireg6'}
DEBUG = {'dcsr','dpc','dscratch0','dscratch1','dexc2dbg','ddcause'}
NEXT_TRAP = {'ustatus','uie','utvec','uscratch','uepc','ucause','utval','uip'}

BLOCK_FEAT = {
 'menvcfg':'U-mode','mcounteren':'U-mode','mcounterwen':'U-mode','mcountermask_u':'U-mode',
 'uzobctl':'U-mode','sleepvalue':'U-mode','umisc_ctl':'U-mode','ucctlbeginaddr':'U-mode/CCTL',
 'mnscratch':'Smrnmi','mnepc':'Smrnmi','mncause':'Smrnmi','mnstatus':'Smrnmi','mnvec':'Smrnmi','mrnxvec':'Smrnmi',
 'mtvt':'CLIC','mintthresh':'CLIC','mirq_entry':'CLIC',
 'mstateen0':'Smstateen','mstateen1':'Smstateen','mstateen2':'Smstateen','mstateen3':'Smstateen',
 'mseccfg':'ePMP',
 'mcctlbeginaddr':'CCTL','mcctldata':'CCTL',
 'mppib':'PPI','mfiob':'FIO',
 'msavestatus':'exc save-levels','msaveepc1':'exc save-levels','msavecause1':'exc save-levels',
 'msaveepc2':'exc save-levels','msavecause2':'exc save-levels','msavedcause1':'exc save-levels','msavedcause2':'exc save-levels',
 'mpft_ctl':'POWERBRAKE','mecc_code':'ECC',
 'mhsp_ctl':'STACKSAFE','msp_bound':'STACKSAFE','msp_base':'STACKSAFE',
 'ucode':'DSP',
 'pmacfg4':'more PMA regions','pmacfg6':'more PMA regions','pmacfg8':'more PMA regions','pmacfg10':'more PMA regions',
}

def classify(addr, priv, name, mode, section):
    kl = norm(name).lower()
    # rule 1: S-mode / Hypervisor
    if mode in ('S-std','S-andes','H-std'):
        return 'na','S/H-mode; outside M/M+U envelope'
    if kl in NA_S:
        return 'na','function needs S-mode; outside envelope'
    # rule 2: read-only / WARL-fixed / hardwired
    if priv in ('MRO','URO','SRO'):
        return 'na','read-only config/info; not transportable'
    if kl == 'misa':
        return 'na','MRW but WARL-fixed to ISA'
    if kl == 'tdata3':
        return 'na','MRW but hardwired 0'
    if kl == 'tinfo':
        return 'na','read-only trigger info'
    # rule 3: RV32-only high-half
    if kl in HIGH_HALF or 'h~' in kl or kl in ODD_PMACFG:
        return 'na','RV32-only high-half on RV64'
    # rule 4: side-effecting / instruction-like
    if kl in SIDE_EFF:
        return 'na','side-effecting/instruction-like'
    # rule 5: indirect-access
    if kl in INDIRECT:
        return 'na','indirect-access mechanism'
    # rule 6: debug-mode-internal
    if kl in DEBUG or priv == 'DRW':
        return 'na','debug-mode-internal'
    # rule 7: W1C/HW-driven; N-ext user trap; udcause
    if priv == 'MRW1C' or kl == 'mcounterovf':
        return 'na','W1C HW-driven status'
    if kl in NEXT_TRAP:
        return 'na','N-ext user trap state'
    if kl == 'udcause':
        return 'na','trap-cause latch'
    # rule 8: transportable M/U state -> done or blocked
    if kl.startswith('pmpcfg') or kl.startswith('pmpaddr'):
        return 'done','M-mode PMP pass-through'
    if kl in ALWAYS_STD:
        return 'done','always-transported std M-mode state'
    if kl in FP:
        return 'done','FP state via fcsr'
    if 'tdata1' in kl:
        return 'done','premium implements + transported'
    if kl in IMPL or norm(name) in DONE_RANGE:
        return 'done','premium implements + transported'
    feat = BLOCK_FEAT.get(kl, 'feature/mode off')
    return 'blocked','in-scope; premium lacks '+feat

# ---- load ----
with open(INV, newline='', encoding='utf-8') as f:
    inv = list(csv.reader(f))
with open(MINE, newline='', encoding='utf-8') as f:
    mine = list(csv.reader(f))

inv_rows = inv[1:]
mine_rows = mine[1:]
assert len(inv_rows) == 232, len(inv_rows)
assert len(mine_rows) == 232, len(mine_rows)

out = [['addr','name','audited_status','your_status','agree','reason']]
agree_n = 0
dis = []
for i,(ir, mr) in enumerate(zip(inv_rows, mine_rows)):
    addr, priv, name, mode, section = ir[0], ir[1], ir[2], ir[3], ir[4]
    m_addr, m_name, m_status = mr[0], mr[1], mr[2]
    assert addr == m_addr, f"row {i}: {addr} != {m_addr}"
    ys, reason = classify(addr, priv, name, mode, section)
    ag = 'yes' if ys == m_status else 'no'
    if ag == 'yes':
        agree_n += 1
    else:
        dis.append((addr, name, m_status, ys, reason))
    assert ',' not in reason, reason
    out.append([addr, name, m_status, ys, ag, reason])

with open(OUT, 'w', newline='', encoding='utf-8') as f:
    csv.writer(f).writerows(out)

print("total rows:", len(out)-1)
print("agree:", agree_n)
print("disagree:", len(dis))
print("--- disagreements ---")
for addr,name,a,y,r in dis:
    print(f"{addr} {name}: {a} -> {y} ({r})")

